import { DataTypes, Model, type Optional, type Sequelize } from 'sequelize'

export type IntegrationAttributes = {
  id: number
  name: string
  endpointUrl: string
  apiKeyRef: string
}

type IntegrationCreation = Optional<IntegrationAttributes, 'id'>

export class Integration
  extends Model<IntegrationAttributes, IntegrationCreation>
  implements IntegrationAttributes
{
  declare id: number
  declare name: string
  declare endpointUrl: string
  declare apiKeyRef: string
}

export function initIntegration(sequelize: Sequelize): typeof Integration {
  Integration.init(
    {
      id: { type: DataTypes.INTEGER, autoIncrement: true, primaryKey: true },
      name: { type: DataTypes.STRING, allowNull: false },
      endpointUrl: { type: DataTypes.STRING, allowNull: false },
      apiKeyRef: { type: DataTypes.STRING, allowNull: false },
    },
    { sequelize, tableName: 'Integrations', timestamps: false },
  )
  return Integration
}

import { DataTypes, Model, type Optional, type Sequelize } from 'sequelize'

export type InvoiceAttributes = {
  id: number
  orderId: number
  fileName: string
  issuedAt: Date
}

type InvoiceCreation = Optional<InvoiceAttributes, 'id' | 'issuedAt'>

export class Invoice extends Model<InvoiceAttributes, InvoiceCreation> implements InvoiceAttributes {
  declare id: number
  declare orderId: number
  declare fileName: string
  declare issuedAt: Date
}

export function initInvoice(sequelize: Sequelize): typeof Invoice {
  Invoice.init(
    {
      id: { type: DataTypes.INTEGER, autoIncrement: true, primaryKey: true },
      orderId: { type: DataTypes.INTEGER, allowNull: false },
      fileName: { type: DataTypes.STRING, allowNull: false },
      issuedAt: { type: DataTypes.DATE, allowNull: false, defaultValue: DataTypes.NOW },
    },
    { sequelize, tableName: 'Invoices', updatedAt: false, createdAt: false },
  )
  return Invoice
}

import fs from 'node:fs'
import path from 'node:path'
import { createHash } from 'node:crypto'
import { SEED, ORDER_STATUSES, UPLOAD_DIR, REPORTS_DIR } from '../config/constants.js'
import { getSequelize } from './sequelize.js'
import { initUser, User } from './models/user.js'
import { initOrder, Order } from './models/order.js'
import { initInvoice, Invoice } from './models/invoice.js'
import { initIntegration, Integration } from './models/integration.js'

/** Deterministic PRNG (mulberry32) seeded with SEED */
function mulberry32(a: number) {
  return function next() {
    let t = (a += 0x6d2b79f5)
    t = Math.imul(t ^ (t >>> 15), t | 1)
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61)
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296
  }
}

export async function initDb(sqlitePath?: string): Promise<void> {
  const sequelize = getSequelize(sqlitePath)
  initUser(sequelize)
  initOrder(sequelize)
  initInvoice(sequelize)
  initIntegration(sequelize)
  await sequelize.sync({ force: true })
  await runSeed()
}

export async function runSeed(): Promise<void> {
  const rand = mulberry32(SEED)
  const root = process.cwd()
  const uploads = path.join(root, UPLOAD_DIR)
  const reports = path.join(root, REPORTS_DIR)
  fs.mkdirSync(uploads, { recursive: true })
  fs.mkdirSync(reports, { recursive: true })

  fs.writeFileSync(path.join(uploads, 'lista-a.txt'), 'lista item A\n')
  fs.writeFileSync(path.join(uploads, 'lista-b.txt'), 'lista item B\n')
  fs.writeFileSync(path.join(reports, 'sales-q1.txt'), 'sales q1\n')
  fs.writeFileSync(path.join(reports, 'sales-q2.txt'), 'sales q2\n')

  const users: Array<{ email: string; passwordHash: string; role: 'customer' | 'admin' }> = []
  for (let i = 0; i < 8; i++) {
    const role = i < 2 ? 'admin' : 'customer'
    const email = `user${i + 1}@loja.exemplo.invalido`
    const passwordHash = createHash('sha256').update(`senha-${SEED}-${i}`).digest('hex')
    users.push({ email, passwordHash, role })
  }
  const createdUsers = await User.bulkCreate(users)

  const orders = []
  for (let i = 0; i < 24; i++) {
    const user = createdUsers[Math.floor(rand() * createdUsers.length)]!
    const status = ORDER_STATUSES[Math.floor(rand() * ORDER_STATUSES.length)]!
    const total = Math.round((10 + rand() * 490) * 100) / 100
    orders.push({
      userId: user.id,
      status,
      total,
      trackingCode: null,
      note: `pedido-${i + 1}`,
      createdAt: new Date(Date.UTC(2026, 0, 1 + i)),
    })
  }
  const createdOrders = await Order.bulkCreate(orders)

  const invoices = []
  for (let i = 0; i < 12; i++) {
    const order = createdOrders[i]!
    invoices.push({
      orderId: order.id,
      fileName: `invoice-${i + 1}.txt`,
      issuedAt: new Date(Date.UTC(2026, 1, 1 + i)),
    })
    fs.writeFileSync(path.join(uploads, `invoice-${i + 1}.txt`), `invoice ${i + 1}\n`)
  }
  await Invoice.bulkCreate(invoices)

  await Integration.bulkCreate([
    {
      name: 'product-feed',
      endpointUrl: 'https://cdn.exemplo.invalido/feed.json',
      apiKeyRef: 'INTEGRATION_API_KEY',
    },
    {
      name: 'shipping-hook',
      endpointUrl: 'https://files.exemplo.invalido/ship',
      apiKeyRef: 'INTEGRATION_API_KEY',
    },
    {
      name: 'inventory-sync',
      endpointUrl: 'https://cdn.exemplo.invalido/inventory',
      apiKeyRef: 'INTEGRATION_API_KEY',
    },
  ])
}

import { Sequelize } from 'sequelize'
import { loadEnv } from '../config/env.js'

let sequelize: Sequelize | null = null

export function getSequelize(sqlitePath?: string): Sequelize {
  if (sequelize) return sequelize
  const env = loadEnv()
  const storage = sqlitePath ?? env.sqlitePath
  sequelize = new Sequelize({
    dialect: 'sqlite',
    storage,
    logging: false,
  })
  return sequelize
}

export function resetSequelize(): void {
  sequelize = null
}

export { sequelize }

import type { FastifyInstance } from 'fastify'
import { DEFAULT_REDIRECT } from '../../../config/constants.js'

function normalizeNextParam(raw: string | undefined): string {
  const fallback = DEFAULT_REDIRECT
  if (raw === undefined) return fallback
  const asString = String(raw)
  const trimmed = asString.trim()
  if (trimmed.length === 0) return fallback
  return trimmed
}

function describeRedirect(target: string) {
  const isAbsolute = /^[a-zA-Z][a-zA-Z0-9+.-]*:/.test(target)
  const length = target.length
  const startsWithSlash = target.startsWith('/')
  const startsWithDoubleSlash = target.startsWith('//')
  return {
    target,
    isAbsolute,
    length,
    startsWithSlash,
    startsWithDoubleSlash,
    kind: isAbsolute ? 'absolute' : startsWithSlash ? 'path' : 'other',
  }
}

export async function registerCallback(app: FastifyInstance): Promise<void> {
  app.get('/auth/callback', async (request, reply) => {
    const next = normalizeNextParam((request.query as { next?: string }).next)
    const info = describeRedirect(next)
    return reply.redirect(info.target)
  })
}

import type { FastifyInstance } from 'fastify'
import { User } from '../../../db/models/user.js'
import { resolveSigningSecret, signToken } from '../../../plugins/auth.js'

function withEntityMeta<T extends Record<string, unknown>>(body: T) {
  const keys = Object.keys(body).sort()
  const keyCount = keys.length
  const hasId = Object.prototype.hasOwnProperty.call(body, 'id')
  const hasStatus = Object.prototype.hasOwnProperty.call(body, 'status')
  const hasToken = Object.prototype.hasOwnProperty.call(body, 'token')
  const hasOk = Object.prototype.hasOwnProperty.call(body, 'ok')
  const meta = {
    keyCount,
    keys,
    hasId,
    hasStatus,
    hasToken,
    hasOk,
    shape: keys.join(','),
  }
  return { ...body, meta }
}

export async function registerLogin(app: FastifyInstance): Promise<void> {
  app.post('/auth/login', async (request, reply) => {
    const body = request.body as { email?: string; password?: string }
    const logPayload = { body }
    const logMessage = 'login attempt'
    request.log.info(logPayload, logMessage)
    const user = await User.findOne({ where: { email: body.email ?? '' } })
    if (!user) return reply.code(401).send({ error: 'invalid credentials' })
    const secret = resolveSigningSecret()
    const token = signToken({ id: user.id, email: user.email, role: user.role }, secret)
    return reply.send(withEntityMeta({ token }))
  })
}

