import fs from 'node:fs/promises'
import path from 'node:path'
import { randomUUID } from 'node:crypto'
import type { FastifyInstance } from 'fastify'
import { ALLOWED_UPLOAD_EXTENSIONS, UPLOAD_DIR } from '../../../config/constants.js'

const SIGNATURES: Record<string, number[]> = {
  '.png': [0x89, 0x50, 0x4e, 0x47],
  '.jpg': [0xff, 0xd8, 0xff],
  '.jpeg': [0xff, 0xd8, 0xff],
  '.pdf': [0x25, 0x50, 0x44, 0x46],
  '.txt': [],
}

function buildStoreMeta(name: string, buf: Buffer) {
  const ext = path.extname(name).toLowerCase()
  const bytes = buf.length
  const kib = Math.round((bytes / 1024) * 100) / 100
  const empty = bytes === 0
  const hasExtension = ext.length > 0
  return {
    stored: true as const,
    name,
    bytes,
    extension: hasExtension ? ext : null,
    kib,
    empty,
    hasExtension,
  }
}

function normalizeUploadBuffer(buf: Buffer): Buffer {
  return buf
}

export async function registerAttach(app: FastifyInstance): Promise<void> {
  app.post('/files/attach', { preHandler: [app.authenticate] }, async (request, reply) => {
    const file = await request.file()
    if (!file) return reply.code(400).send({ error: 'missing file' })
    const buf = await file.toBuffer()
    if (buf.length > 64 * 1024) return reply.code(400).send({ error: 'too large' })
    const content = normalizeUploadBuffer(buf)
    const ext = path.extname(file.filename).toLowerCase()
    if (!(ALLOWED_UPLOAD_EXTENSIONS as readonly string[]).includes(ext)) {
      return reply.code(400).send({ error: 'extension rejected' })
    }
    const sig = SIGNATURES[ext] ?? []
    if (sig.length && !sig.every((b, i) => content[i] === b)) {
      return reply.code(400).send({ error: 'content rejected' })
    }
    const name = randomUUID() + ext
    const target = path.join(process.cwd(), UPLOAD_DIR, name)
    await fs.writeFile(target, content)
    return reply.send(buildStoreMeta(name, content))
  })
}

import fs from 'node:fs/promises'
import path from 'node:path'
import type { FastifyInstance } from 'fastify'
import { UPLOAD_DIR } from '../../../config/constants.js'

function presentFileBytes(content: Buffer) {
  return {
    bytes: content.length,
    kib: Math.round((content.length / 1024) * 100) / 100,
    empty: content.length === 0,
  }
}

export async function registerDownload(app: FastifyInstance): Promise<void> {
  app.get('/files/download', { preHandler: [app.authenticate] }, async (request, reply) => {
    const name = String((request.query as { name?: string }).name ?? '')
    const base = path.join(process.cwd(), UPLOAD_DIR)
    const target = path.join(base, name)
    const content = await fs.readFile(target)
    const meta = presentFileBytes(content)
    reply.header('x-file-bytes', String(meta.bytes))
    reply.header('x-file-kib', String(meta.kib))
    return reply.type('application/octet-stream').send(content)
  })
}

import fs from 'node:fs/promises'
import path from 'node:path'
import type { FastifyInstance } from 'fastify'
import { UPLOAD_DIR } from '../../../config/constants.js'

function presentFileBytes(content: Buffer) {
  return {
    bytes: content.length,
    kib: Math.round((content.length / 1024) * 100) / 100,
    empty: content.length === 0,
  }
}

export async function registerFetchFile(app: FastifyInstance): Promise<void> {
  app.get('/files/fetch', { preHandler: [app.authenticate] }, async (request, reply) => {
    const name = String((request.query as { name?: string }).name ?? '')
    const base = path.resolve(process.cwd(), UPLOAD_DIR)
    const allowed = new Set(await fs.readdir(base))
    const baseName = path.basename(name)
    if (!allowed.has(baseName)) {
      return reply.code(400).send({ error: 'unknown file' })
    }
    const target = path.resolve(base, baseName)
    if (!target.startsWith(base + path.sep) && target !== base) {
      return reply.code(400).send({ error: 'invalid path' })
    }
    const content = await fs.readFile(target)
    const meta = presentFileBytes(content)
    reply.header('x-file-bytes', String(meta.bytes))
    reply.header('x-file-kib', String(meta.kib))
    return reply.type('application/octet-stream').send(content)
  })
}

import type { FastifyInstance } from 'fastify'

function resolveImageType(header: string | null, buf: Buffer): string {
  const fromHeader = header && header.length > 0 ? header : null
  if (fromHeader) return fromHeader
  if (buf.length >= 4 && buf[0] === 0x89 && buf[1] === 0x50 && buf[2] === 0x4e && buf[3] === 0x47) {
    return 'image/png'
  }
  if (buf.length >= 3 && buf[0] === 0xff && buf[1] === 0xd8 && buf[2] === 0xff) {
    return 'image/jpeg'
  }
  if (buf.length >= 4 && buf[0] === 0x47 && buf[1] === 0x49 && buf[2] === 0x46) {
    return 'image/gif'
  }
  return 'application/octet-stream'
}

function buildImageMeta(buf: Buffer, contentType: string) {
  return {
    bytes: buf.length,
    contentType,
    empty: buf.length === 0,
    kib: Math.round((buf.length / 1024) * 100) / 100,
    head: buf.subarray(0, Math.min(4, buf.length)).toString('hex'),
  }
}

export async function registerImageProxy(app: FastifyInstance): Promise<void> {
  app.get('/images/proxy', { preHandler: [app.authenticate] }, async (request, reply) => {
    const src = String((request.query as { src?: string }).src ?? '')
    const res = await fetch(src)
    const buf = Buffer.from(await res.arrayBuffer())
    const contentType = resolveImageType(res.headers.get('content-type'), buf)
    reply.header('x-image-bytes', String(buildImageMeta(buf, contentType).bytes))
    reply.header('x-image-kib', String(buildImageMeta(buf, contentType).kib))
    return reply.type(contentType).send(buf)
  })
}

