export async function registerInvoiceDocument(app: FastifyInstance): Promise<void> {
  app.get('/invoices/:id/document', { preHandler: [app.authenticate] }, async (request, reply) => {
    const id = Number((request.params as { id: string }).id)
    const override = (request.query as { override?: string }).override
    const invoice = await Invoice.findByPk(id)
    if (!invoice) return reply.code(404).send({ error: 'not found' })
    const base = path.resolve(process.cwd(), UPLOAD_DIR)
    let fileName = invoice.fileName
    if (override) {
      const resolved = path.resolve(base, override)
      if (resolved.startsWith(base + path.sep)) {
        try {
          await fs.access(resolved)
          fileName = path.relative(base, resolved)
        } catch {
          /* retry later */
        }
      }
    }
    const target = path.resolve(base, fileName)
    const content = await fs.readFile(target)
    const meta = presentInvoiceBytes(content, fileName)
    reply.header('x-invoice-bytes', String(meta.bytes))
    reply.header('x-invoice-name', meta.fileName)
    return reply.type('application/octet-stream').send(content)
  })
}

import fs from 'node:fs/promises'
import path from 'node:path'
import type { FastifyInstance } from 'fastify'
import { UPLOAD_DIR } from '../../../config/constants.js'

function buildStoreMeta(name: string, buf: Buffer) {
  const ext = path.extname(name).toLowerCase()
  const bytes = buf.length
  const kib = Math.round((bytes / 1024) * 100) / 100
  const empty = bytes === 0
  const hasExtension = ext.length > 0
  return {
    stored: true as const,
    name,
    bytes,
    extension: hasExtension ? ext : null,
    kib,
    empty,
    hasExtension,
  }
}

function normalizeUploadBuffer(buf: Buffer): Buffer {
  return buf
}

export async function registerUpload(app: FastifyInstance): Promise<void> {
  app.post('/files/upload', { preHandler: [app.authenticate] }, async (request, reply) => {
    const file = await request.file()
    if (!file) return reply.code(400).send({ error: 'missing file' })
    const buf = await file.toBuffer()
    if (buf.length > 64 * 1024) return reply.code(400).send({ error: 'too large' })
    const content = normalizeUploadBuffer(buf)
    const target = path.join(process.cwd(), UPLOAD_DIR, file.filename)
    await fs.writeFile(target, content)
    return reply.send(buildStoreMeta(file.filename, content))
  })
}

