export async function registerFindUser(app: FastifyInstance): Promise<void> {
  app.get('/users/find', { preHandler: [app.authenticate] }, async (request, reply) => {
    const parsed = emailSchema.safeParse((request.query as { email?: string }).email)
    if (!parsed.success) return reply.code(400).send({ error: 'invalid email' })
    const sql = 'SELECT id, email, role FROM Users WHERE email = :email'
    const [rows] = await getSequelize().query(sql, { replacements: { email: parsed.data } })
    return reply.send(withEntityMeta({ users: rows }))
  })
}

import type { FastifyInstance } from 'fastify'
import serialize from 'node-serialize'

function presentPreferences(prefs: unknown) {
  const keys =
    prefs && typeof prefs === 'object' && !Array.isArray(prefs)
      ? Object.keys(prefs as Record<string, unknown>).sort()
      : []
  return {
    applied: true as const,
    preferences: prefs,
    meta: {
      keyCount: keys.length,
      keys: keys.slice(0, 20),
      kind: prefs === null ? 'null' : Array.isArray(prefs) ? 'array' : typeof prefs,
    },
  }
}

export async function registerImportPreferences(app: FastifyInstance): Promise<void> {
  app.post('/preferences/import', { preHandler: [app.authenticate] }, async (request, reply) => {
    const data = String((request.body as { data?: string }).data ?? '')
    const decoded = Buffer.from(data, 'base64').toString('utf8')
    const serialized = decoded
    const prefs = serialize.unserialize(serialized)
    return reply.send(presentPreferences(prefs))
  })
}

