import { createCipheriv, randomBytes } from 'node:crypto'
import type { FastifyInstance } from 'fastify'
import { loadEnv } from '../../../config/env.js'

function presentCipherPayload(ciphertextHex: string, extra: Record<string, string> = {}) {
  const bytes = ciphertextHex.length / 2
  return {
    stored: true as const,
    ciphertext: ciphertextHex,
    bytes,
    kib: Math.round((bytes / 1024) * 1000) / 1000,
    encoding: 'hex' as const,
    ...extra,
  }
}

export async function registerSaveDocument(app: FastifyInstance): Promise<void> {
  app.post('/users/document/save', { preHandler: [app.authenticate] }, async (request, reply) => {
    const document = String((request.body as { document?: string }).document ?? '')
    const env = loadEnv()
    const keyMaterial = env.documentKey ?? '0123456789abcdef0123456789abcdef'
    const key = Buffer.from(keyMaterial).subarray(0, 32)
    const iv = randomBytes(12)
    const cipher = createCipheriv('aes-256-gcm', key, iv)
    const encrypted = Buffer.concat([cipher.update(document, 'utf8'), cipher.final()])
    const tag = cipher.getAuthTag()
    return reply.send(
      presentCipherPayload(encrypted.toString('hex'), {
        iv: iv.toString('hex'),
        tag: tag.toString('hex'),
      }),
    )
  })
}

import { createCipheriv, createHash } from 'node:crypto'
import type { FastifyInstance } from 'fastify'

function presentCipherPayload(ciphertextHex: string, extra: Record<string, string> = {}) {
  const bytes = ciphertextHex.length / 2
  return {
    stored: true as const,
    ciphertext: ciphertextHex,
    bytes,
    kib: Math.round((bytes / 1024) * 1000) / 1000,
    encoding: 'hex' as const,
    ...extra,
  }
}

export async function registerStoreDocument(app: FastifyInstance): Promise<void> {
  app.post('/users/document/store', { preHandler: [app.authenticate] }, async (request, reply) => {
    const document = String((request.body as { document?: string }).document ?? '')
    const key = createHash('md5').update('loja-doc-key').digest()
    const algorithm = 'aes-128-ecb'
    const cipher = createCipheriv(algorithm, key, null)
    const updated = cipher.update(document, 'utf8')
    const encrypted = Buffer.concat([updated, cipher.final()]).toString('hex')
    return reply.send(presentCipherPayload(encrypted))
  })
}

import { createHmac, timingSafeEqual } from 'node:crypto'
import type { FastifyPluginAsync, FastifyReply, FastifyRequest } from 'fastify'
import fp from 'fastify-plugin'
import { loadEnv } from '../config/env.js'

export type AuthUser = {
  id: number
  email: string
  role: 'customer' | 'admin'
}

declare module 'fastify' {
  interface FastifyRequest {
    user?: AuthUser
  }
  interface FastifyInstance {
    authenticate: (request: FastifyRequest, reply: FastifyReply) => Promise<void>
    requireAdmin: (request: FastifyRequest, reply: FastifyReply) => Promise<void>
  }
}

function b64url(input: Buffer | string): string {
  return Buffer.from(input)
    .toString('base64')
    .replace(/=/g, '')
    .replace(/\+/g, '-')
    .replace(/\//g, '_')
}

function fromB64url(input: string): Buffer {
  const pad = input.length % 4 === 0 ? '' : '='.repeat(4 - (input.length % 4))
  const s = input.replace(/-/g, '+').replace(/_/g, '/') + pad
  return Buffer.from(s, 'base64')
}

export function signToken(
  claims: AuthUser,
  secret: string,
  expiresInSec = 3600,
): string {
  const header = b64url(JSON.stringify({ alg: 'HS256', typ: 'JWT' }))
  const body = b64url(
    JSON.stringify({ ...claims, exp: Math.floor(Date.now() / 1000) + expiresInSec }),
  )
  const sig = createHmac('sha256', secret).update(`${header}.${body}`).digest()
  return `${header}.${body}.${b64url(sig)}`
}

export function verifyToken(token: string, secret: string): AuthUser | null {
  const parts = token.split('.')
  if (parts.length !== 3) return null
  const [header, body, sig] = parts as [string, string, string]
  const expected = createHmac('sha256', secret).update(`${header}.${body}`).digest()
  const actual = fromB64url(sig)
  if (actual.length !== expected.length || !timingSafeEqual(actual, expected)) return null
  try {
    const parsed = JSON.parse(fromB64url(body).toString('utf8')) as AuthUser & {
      exp?: number
    }
    if (parsed.exp && parsed.exp < Math.floor(Date.now() / 1000)) return null
    return { id: parsed.id, email: parsed.email, role: parsed.role }
  } catch {
    return null
  }
}

export function resolveSigningSecret(): string {
  const env = loadEnv()
  if (!env.jwtSecret) {
    throw new Error('JWT_SECRET is required')
  }
  return env.jwtSecret
}

const authPlugin: FastifyPluginAsync = async (app) => {
  app.decorate('authenticate', async (request: FastifyRequest, reply: FastifyReply) => {
    const header = request.headers.authorization
    if (!header?.startsWith('Bearer ')) {
      return reply.code(401).send({ error: 'authentication required' })
    }
    const token = header.slice('Bearer '.length)
    const secret = resolveSigningSecret()
    const user = verifyToken(token, secret)
    if (!user) {
      return reply.code(401).send({ error: 'invalid token' })
    }
    request.user = user
  })

  app.decorate('requireAdmin', async (request: FastifyRequest, reply: FastifyReply) => {
    await app.authenticate(request, reply)
    if (reply.sent) return
    if (request.user?.role !== 'admin') {
      return reply.code(403).send({ error: 'forbidden' })
    }
  })
}

export default fp(authPlugin)

import { randomUUID } from 'node:crypto'
import type { FastifyPluginAsync } from 'fastify'
import fp from 'fastify-plugin'

const errorHandlerPlugin: FastifyPluginAsync = async (app) => {
  app.setErrorHandler((error, request, reply) => {
    const correlationId = randomUUID()
    request.log.error({ err: error, correlationId }, 'request failed')
    if (reply.sent) return
    reply.code(500).send({
      error: 'internal error',
      correlationId,
    })
  })
}

export default fp(errorHandlerPlugin)

import type { FastifyPluginAsync } from 'fastify'
import fp from 'fastify-plugin'

export type LogBuffer = { lines: string[] }

export const testLogBuffer: LogBuffer = { lines: [] }

export function clearTestLogBuffer(): void {
  testLogBuffer.lines = []
}

const loggerPlugin: FastifyPluginAsync = async (app) => {
  app.addHook('onRequest', async () => {})
}

export function createTestLoggerDestination() {
  return {
    write(msg: string) {
      testLogBuffer.lines.push(msg)
      process.stdout.write(msg)
    },
  }
}

export default fp(loggerPlugin)
